import React, { useEffect, useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { AuthContext } from "../context/AuthContext";
import "./Emergency.css";

const Emergency = () => {
  const navigate = useNavigate();
  const { user } = useContext(AuthContext); // get logged-in user
  const [contacts, setContacts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [locationText, setLocationText] = useState("Detecting location...");
  const [newName, setNewName] = useState("");
  const [newPhone, setNewPhone] = useState("");
  const [newRelation, setNewRelation] = useState("");
  const [error, setError] = useState("");

  // Fetch contacts for logged-in user
  const fetchContacts = async () => {
    if (!user?._id) return;
    setLoading(true);
    try {
      const res = await axios.get(
        `http://localhost:5001/api/personal-contacts/${user._id}`
      );
      setContacts(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchContacts();
  }, [user]);

  // Get location
  useEffect(() => {
    if (!navigator.geolocation) {
      setLocationText("Location not supported");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const lat = position.coords.latitude;
        const lon = position.coords.longitude;

        try {
          const res = await axios.get(
            `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`
          );

          const country = res.data.address.country;
          const state = res.data.address.state || "";
          const city =
            res.data.address.city ||
            res.data.address.town ||
            res.data.address.village ||
            "";

          setLocationText(`📍 ${city}, ${state}, ${country}`);
        } catch (error) {
          setLocationText("📍 Location detected (India)");
        }
      },
      () => {
        setLocationText("📍 Location permission denied");
      },
      { enableHighAccuracy: true }
    );
  }, []);

  // Handle call
  const handleCall = async (contact) => {
    if (!navigator.geolocation) {
      await saveCall(contact, null, null);
      window.location.href = `tel:${contact.phoneNumber}`;
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        await saveCall(
          contact,
          position.coords.latitude,
          position.coords.longitude
        );
        window.location.href = `tel:${contact.phoneNumber}`;
      },
      async () => {
        await saveCall(contact, null, null);
        window.location.href = `tel:${contact.phoneNumber}`;
      }
    );
  };

  // Save call to backend
  const saveCall = async (contact, latitude, longitude) => {
    try {
      await axios.post("http://localhost:5001/api/emergency-calls", {
        contactName: contact.name,
        phoneNumber: contact.phoneNumber,
        latitude,
        longitude,
      });
    } catch (error) {
      console.error("Error saving call");
    }
  };

  // Add new contact
  const handleAddContact = async (e) => {
    e.preventDefault();
    setError("");

    if (!user?._id) {
      setError("Please login first.");
      return;
    }
    if (!newName || !newPhone) {
      setError("Name and Phone Number are required.");
      return;
    }

    try {
      await axios.post("http://localhost:5001/api/personal-contacts", {
        userId: user._id,
        name: newName,
        phoneNumber: newPhone,
        relation: newRelation,
      });

      // Clear form
      setNewName("");
      setNewPhone("");
      setNewRelation("");

      fetchContacts(); // reload contacts
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Failed to add contact");
    }
  };

  return (
    <div className="emergency-container">
      <h1>🚨 Emergency Contacts</h1>

      <div className="location-box">
        <strong>Your Location:</strong> {locationText}
      </div>

      {/* Add new contact form */}
      <div className="add-contact-form">
        <h2>Add Personal Contact</h2>
        {error && <p className="error">{error}</p>}
        <form onSubmit={handleAddContact}>
          <input
            type="text"
            placeholder="Name"
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
            required
          />
          <input
            type="text"
            placeholder="Phone Number"
            value={newPhone}
            onChange={(e) => setNewPhone(e.target.value)}
            required
          />
          <input
            type="text"
            placeholder="Relation (optional)"
            value={newRelation}
            onChange={(e) => setNewRelation(e.target.value)}
          />
          <button type="submit">Add Contact</button>
        </form>
      </div>

      {/* Contact list */}
      {loading ? (
        <p>Loading contacts...</p>
      ) : (
        <div className="contact-grid">
          {contacts.map((contact) => (
            <div key={contact._id} className="contact-card">
              <h3>{contact.name}</h3>
              <p>{contact.phoneNumber}</p>
              {contact.relation && <p>Relation: {contact.relation}</p>}
              <button
                className="call-btn"
                onClick={() => handleCall(contact)}
              >
                📞 Call Now
              </button>
            </div>
          ))}
        </div>
      )}

      <button className="back-btn" onClick={() => navigate("/")}>
        ⬅ Back to Home
      </button>
    </div>
  );
};

export default Emergency;
